// ---------------------------------------------------------------------------
// WHAT EACH NETWORK NEEDS BEFORE THE UNIVERSITY CAN POST TO IT.
//
// WHY THIS FILE IS HONEST INSTEAD OF CLEVER.
//
// Every one of these platforms requires an OAuth application registered by the
// institution under its own name, reviewed by the platform, and granted the
// specific permissions listed below. None of that can be generated by this
// system, faked, or worked around — a "post to Facebook" button without a Meta
// app behind it is a button that fails, and the failure arrives after a
// graduation when somebody asks why the announcement never appeared.
//
// So the Command Centre asks this module which platforms are actually
// configured, offers only those, and says plainly what is missing for the rest.
// An administrator is never shown a destination the system cannot reach.
//
// THE REVIEW TIMES ARE REAL AND THEY MATTER FOR PLANNING. Meta's App Review for
// content publishing permissions and TikTok's Content Posting API audit both
// take weeks and both require a working privacy policy and a demonstration
// video. A university that decides in September to announce its graduation in
// October should start these applications in September.
// ---------------------------------------------------------------------------

import { PLATFORMS, type Platform } from '@/lib/social';

export interface ProviderRequirement {
  platform: Platform;
  /** The application the university registers, and where. */
  app: string;
  /** Environment variables that must be set for this platform to work. */
  env: string[];
  /** The permissions the app must be granted. */
  scopes: string[];
  /** What the university has to do that is not a form. */
  note: string;
}

