/**
 * Which platforms this deployment can actually reach.
 *
 * SERVER-SIDE ONLY. It reads process.env, which is empty in the browser — and
 * that is the right way round: the answer is about the deployment, and a client
 * that decided for itself would be deciding from nothing.
 */
export function configuredProviders(env: NodeJS.ProcessEnv = process.env): Platform[] {
  return PLATFORMS.filter((p) =>
    PROVIDER_REQUIREMENTS[p].env.every((key) => Boolean(env[key]?.trim())));
}

/** What is missing for one platform, for an error message a person can act on. */
export function missingFor(platform: Platform, env: NodeJS.ProcessEnv = process.env): string[] {
  return PROVIDER_REQUIREMENTS[platform].env.filter((key) => !env[key]?.trim());
}

/**
 * The sentence shown when somebody tries to connect a platform that is not set up.
 *
 * NAMES THE VARIABLES. "Not configured" sends an administrator to ask a
 * developer; "META_APP_ID and META_APP_SECRET are not set" sends them to the
 * Vercel dashboard, where they can fix it themselves.
 */
export function explainMissing(platform: Platform, env: NodeJS.ProcessEnv = process.env): string {
  const missing = missingFor(platform, env);
  if (missing.length === 0) return '';
  const r = PROVIDER_REQUIREMENTS[platform];
  return `${platform} is not connected to this deployment: ${missing.join(', ')} ${
    missing.length === 1 ? 'is' : 'are'} not set. ${r.app} See docs/SOCIAL-CONNECTIONS.md.`;
}
